import json,re
from pathlib import Path
P=Path('research/non-ml-math-remaining-81-2026-10-18-owner-step2-battery-boundaries-qre')
d=json.load(open(P/'row-patches.json'));o=json.load(open(P/'hn-closure-observation.json'))
uses={
'lem-it-square-root-cq-packing-bound':'Fact F3 and proof 2.1 instantiate S as one compressed projector and T as the sum of the remaining compressed projectors. The former is an effect and the latter positive; the support inverse convention and coefficients two and four remain exactly those of the repaired lemma. No consumer change.',
'lem-it-finite-cq-wiretap-strong-secrecy-achievability':'Fact F4 and proof 2.1 use S=Gamma for a transmitted pair and T=sum of all other pair effects. Each Gamma is bounded by the global projection and therefore by identity; the competitor sum is positive. The corrected common-kernel block retains failure-outcome handling and the same two/four error coefficients. No consumer change.',
 'thm-it-hsw-classical-quantum-channel-capacity':'The packing premise F5 and its direct-code application use the unchanged expected-error estimate. The finite-codebook selection and strict rate slack remain valid after the proof-only supplier correction. No source or premise-quote change.',
 'thm-it-quantum-channel-capacity-regularized-private-information':'The direct part uses F9 wiretap strong-secrecy achievability. Its receiver error bound has unchanged coefficients and exponential decay; mixed input encoding, unnormalized Holevo leakage and the Fano converse are untouched. No source change.',
 'ex-it-cq-binary-pure-state-channel':'The example invokes HSW for rates below its computed binary ensemble information. Neither the overlap eigenvalues nor the strict-rate HSW interface changes. No source change.',
 'lem-it-flat-input-entanglement-assisted-achievability':'The Weyl cq alphabet invokes HSW through F1. The alphabet, its Holevo identity and below-value coding use only the unchanged HSW export, not the internal operator-inequality last line. No source change.',
 'thm-it-degradable-channel-single-letter-capacities':'The regularized private formula in F4 is used after coherent-information bounds and a finite pure-state ensemble give matching information optima. The private operational export remains unchanged. No source change.',
 'thm-it-entanglement-assisted-classical-capacity-additive-formula':'The direct proof uses the flat-input assisted coding export and HSW; the arbitrary-shared-state converse is independent of the repaired block argument. All operational and information interfaces are unchanged. No source change.',
 'thm-it-qudit-erasure-channel-exact-capacities':'The general private/assisted and degradable formulas are used only at their unchanged exported capacity values. Erasure endpoint and half-erasure calculations remain exactly as before. No source change.',
 'ex-it-noiseless-qubit-entanglement-assisted-capacity':'The example substitutes the identity qubit into the unchanged assisted capacity formula and supplies its explicit four-word Bell code. No source change.',
 'ex-it-qudit-erasure-channel-capacity-regimes':'The table substitutes probabilities into the unchanged exact erasure capacity formulas. No supplier proof-step quotation occurs and no source change is needed.'}
rows=[]
for x in o['items']:
 if x['distance']==0:continue
 t=Path(x['source']).read_text();assert x['id'] in uses
 rows.append(dict(x,actual_use=uses[x['id']],disposition='unchanged interface; no proposed consumer edit',read_record='Current consumer Statement/Example, Facts and complete proof/verification inspected for the affected interface; existing full same-owner accepted review reused.'))
ids={o['seed']}|set(uses)
pages=[]
for p in Path('library').rglob('*.md'):
 t=p.read_text();hits=sorted(x for x in ids if x in t)
 if hits:pages.append({'page':str(p),'references':hits,'disposition':'Inventory/navigation or unchanged exported claim references; no claim, ownership or reading-path change is introduced by this proof-only repair.'})
(P/'hayashi-nagaoka-consumer-dispositions.json').write_text(json.dumps({'run':d['run'],'supplier':o['seed'],'supplier_status_observed':'draft','change':'Proof 2.1 only; Statement, facts, dependencies and all metadata unchanged.','direct_consumers':2,'transitive_consumers':len(rows),'items':rows,'pages':pages,'closure_method':'Current item deps and all textual wikilinks, followed transitively; page references separately enumerated. This is not a new publication/native worker coverage claim.','contract_followthrough':'Root should regenerate only the supplier step 2.1 exact derivation quotation and any complete-proof excerpt that includes it; consumer Fact quotations and all Statements are unchanged. Boundary rows remain subject to root current-input binding.','checks':'No validators, production gates, native counters, canonical writes or source hashes generated by this packet.'},indent=2)+'\n')
# Packet completeness and source-currency observations, not a gate or validator result.
a=json.load(open('research/'+d['run']+'-owner-step2-first-battery-failures/boundary-assignment-qre.json'))
expected={(s['id'],r['original']['case']) for s in a['subjects'] for r in s['rows']};actual={(p['id'],p['case']) for p in d['patches']}
assert expected==actual and len(actual)==478
by={s['id']:s for s in a['subjects']}
assert all(p['original']==next(r['original'] for r in by[p['id']]['rows'] if r['original']['case']==p['case']) for p in d['patches'])
drift=[s['source'] for s in a['subjects'] if Path(s['source']).read_bytes()!=(P/'before'/s['source']).read_bytes()]
(P/'packet-accounting.json').write_text(json.dumps({'expected_items':83,'review_records':len(d['item_reviews']),'expected_rows':478,'exact_original_rows_preserved':True,'missing_or_duplicate_rows':0,'status_corrections':sum(p['original']['status']!=p['proposed']['status'] for p in d['patches']),'current_source_drift_since_packet_snapshot':drift,'root_obligations':'Actual item/row hash binding, metadata installation, contracts and all appropriate checks/gates. Packet accounting is not gate credit.','preserved_packets':'All previous frozen same-owner packets left unchanged.'},indent=2)+'\n')
print({'rows':len(actual),'consumer_items':len(rows),'pages':len(pages),'source_drift':drift})
